import 'dart:async';import 'package:flutter/foundation.dart';import 'package:flutter/material.dart';import 'package:sizer/sizer.dart';import 'package:smart_coach_new/core/utils/enums.dart';import 'package:smart_coach_new/core/widgets/custom_text_field.dart';import 'package:smart_coach_new/core/widgets/grid_table_header_view.dart';import 'package:smart_coach_new/features/user_management/domain/entities/user_entity.dart';import 'package:syncfusion_flutter_core/theme.dart';import 'package:syncfusion_flutter_datagrid/datagrid.dart';class SearchParams {  final List<UserEntity> users;  final String query;  SearchParams(this.users, this.query);}List<UserEntity> _filterUsers(SearchParams params) {  final query = params.query.toLowerCase();  return params.users.where((user) {    return [      user.firstName,      user.lastName,      user.mobileNumber?.toString(),      user.email,      user.organisationType,      user.role,      user.employeeId,      user.panCardNo,      user.aadharNo    ].any((field) => field?.toLowerCase().contains(query) ?? false);  }).toList();}class UserTable extends StatefulWidget {  final List<UserEntity> users;  final List<UserEntity> selectedUsers;  final Function(UserEntity user) onSelectUser;  final Function(UserEntity user) onUnSelectUser;  final Function(int? userId, String status) onApproveReject;  final Function(UserEntity user) onTapEdit;  final bool isShowingApprovedUsers;  const UserTable(      {super.key,        required this.users,        required this.selectedUsers,        required this.onSelectUser,        required this.onUnSelectUser,        required this.onApproveReject,        required this.onTapEdit,        this.isShowingApprovedUsers = false});  @override  State<UserTable> createState() => _UserTableState();}class _UserTableState extends State<UserTable> {  late UserDataSource _dataSource;  final DataGridController _controller = DataGridController();  final TextEditingController _searchController = TextEditingController();  String _searchText = '';  Timer? _debounce;  @override  void initState() {    _buildDataSource();    super.initState();  }  @override  void didUpdateWidget(covariant UserTable oldWidget) {    super.didUpdateWidget(oldWidget);    // Rebuild data source when props (users or selectedUsers) change    if (widget.users != oldWidget.users ||        widget.selectedUsers != oldWidget.selectedUsers) {      _buildDataSource();    }  }  @override  void dispose() {    _debounce?.cancel();    _searchController.dispose();    super.dispose();  }  void _buildDataSource() async {    final usersToFilter = widget.users;    List<UserEntity> filteredUsers;    if (_searchText.isEmpty) {      filteredUsers = usersToFilter;    } else {      filteredUsers =      await compute(_filterUsers, SearchParams(usersToFilter, _searchText));    }    setState(() {      _dataSource = UserDataSource(        users: filteredUsers,        selectedUsers: widget.selectedUsers,        onSelectUser: widget.onSelectUser,        onUnSelectUser: widget.onUnSelectUser,        onApproveReject: widget.onApproveReject,        onTapEdit: widget.onTapEdit,        isShowingApprovedUsers: widget.isShowingApprovedUsers,      );    });  }  void _onSearchChanged(String value) {    if (_debounce?.isActive ?? false) _debounce?.cancel();    _debounce = Timer(Duration(milliseconds: 300), () {      setState(() {        _searchText = value.toLowerCase();      });      _buildDataSource();    });  }  @override  Widget build(BuildContext context) {    final bool showSearch = true;    final bool hasSearch = _searchText.isNotEmpty;    return Column(      children: [        if (showSearch)          Padding(            padding: EdgeInsets.symmetric(horizontal: 8.0, vertical: 4.0),            child: CustomTextField(              controller: _searchController,              hintText: 'Search by any field...',              labelText: 'Search',              prefixIcon: Icons.search,              onChanged: _onSearchChanged,              showShadowOnTextField: true,              suffixIcon: hasSearch                  ? GestureDetector(                onTap: () {                  _searchController.clear();                  _onSearchChanged('');                },                child: Icon(Icons.clear, color: Colors.black, size: 18),              )                  : null,            ),          ),        Expanded(          child: Padding(            padding: EdgeInsets.all(2.w),            child: ClipRRect(              borderRadius: BorderRadius.circular(2.w),              child: Container(                decoration: BoxDecoration(                  color: Colors.white,                  borderRadius: BorderRadius.circular(2.w),                  border: Border.all(color: Colors.grey.shade300),                ),                child: SfDataGridTheme(                  data: SfDataGridThemeData(                    headerColor: Colors.grey.shade100,                    headerHoverColor: Colors.grey.shade200,                  ),                  child: SfDataGrid(                    controller: _controller,                    source: _dataSource,                    allowSorting: true,                    selectionMode: SelectionMode.multiple,                    showCheckboxColumn: true,                    columnWidthMode: ColumnWidthMode.fitByCellValue,                    isScrollbarAlwaysShown: true,                    onSelectionChanged:                        (List<DataGridRow> added, List<DataGridRow> removed) {                      _dataSource.handleSelectionChanged(added, removed);                    },                    gridLinesVisibility: GridLinesVisibility.both,                    headerGridLinesVisibility: GridLinesVisibility.both,                    columns: [                      GridColumn(                        columnName: 'First Name',                        label: GridTableHeaderView(                          'First Name',                        ),                      ),                      GridColumn(                        columnName: 'Last Name',                        label: GridTableHeaderView(                          'Last Name',                        ),                      ),                      GridColumn(                        columnName: 'Mobile',                        label: GridTableHeaderView(                          'Mobile',                        ),                      ),                      GridColumn(                        columnName: 'Email',                        label: GridTableHeaderView(                          'Email',                        ),                      ),                      GridColumn(                        columnName: 'Organization',                        label: GridTableHeaderView(                          'Organization',                        ),                      ),                      GridColumn(                        columnName: 'Job Role',                        label: GridTableHeaderView(                          'Job Role',                        ),                      ),                      GridColumn(                        columnName: 'ID',                        label: GridTableHeaderView(                          'ID',                        ),                      ),                      GridColumn(                        columnName: 'PAN',                        label: GridTableHeaderView('PAN'),                        allowSorting: false,                      ),                      GridColumn(                        columnName: 'Adhar',                        label: GridTableHeaderView('Adhar'),                        allowSorting: false,                      ),                      GridColumn(                        columnName: 'Photo',                        label: GridTableHeaderView('Photo'),                        width: 25.w,                        allowSorting: false,                      ),                      GridColumn(                        columnName: 'Status',                        label: GridTableHeaderView('Status'),                        width: 60.w,                        allowSorting: false,                      ),                    ],                  ),                ),              ),            ),          ),        ),      ],    );  }}class UserDataSource extends DataGridSource {  final List<UserEntity> users;  final List<UserEntity> selectedUsers;  final Function(UserEntity user) onSelectUser;  final Function(UserEntity user) onUnSelectUser;  final Function(int? userId, String status) onApproveReject;  final Function(UserEntity user) onTapEdit;  final bool isShowingApprovedUsers;  List<DataGridRow> _rows = [];  @override  List<DataGridRow> get rows => _rows;  final List<DataGridRow> _selectedRows = [];  UserDataSource(      {required this.users,        required this.selectedUsers,        required this.onSelectUser,        required this.onUnSelectUser,        required this.onApproveReject,        required this.onTapEdit,        required this.isShowingApprovedUsers}) {    String emptyText = '----';    _rows = users.map((user) {      return DataGridRow(cells: [        DataGridCell<String>(            columnName: 'First Name', value: user.firstName ?? emptyText),        DataGridCell<String>(            columnName: 'Last Name', value: user.lastName ?? emptyText),        DataGridCell<String>(            columnName: 'Mobile',            value: (user.mobileNumber ?? emptyText).toString()),        DataGridCell<String>(            columnName: 'Email', value: user.email ?? emptyText),        DataGridCell<String>(            columnName: 'Organization',            value: user.organisationType ?? emptyText),        DataGridCell<String>(            columnName: 'Job Role', value: user.role ?? emptyText),        DataGridCell<String>(            columnName: 'ID', value: user.employeeId ?? emptyText),        DataGridCell<String>(            columnName: 'PAN', value: user.panCardNo ?? emptyText),        DataGridCell<String>(            columnName: 'Adhar', value: user.aadharNo ?? emptyText),        DataGridCell<String>(columnName: 'Photo', value: ''),        DataGridCell<String>(            columnName: 'Status', value: user.approvalStatus ?? emptyText),      ]);    }).toList();  }  @override  DataGridRowAdapter buildRow(DataGridRow row) {    final int rowIndex = _rows.indexOf(row);    final user = users[rowIndex];    return DataGridRowAdapter(      color: _selectedRows.contains(row) ? Colors.grey.shade200 : null,      cells: row.getCells().map((cell) {        if (cell.columnName == 'Photo') {          return Center(            child: CircleAvatar(              radius: 1.8.h,              backgroundImage:              (cell.value != null && cell.value.toString().isNotEmpty)                  ? NetworkImage(cell.value)                  : null,            ),          );        } else if (cell.columnName == 'Status') {          bool isApproved = cell.value.toLowerCase() == UserApprovalStatus.approved.name.toLowerCase();          bool isRejected = cell.value.toLowerCase() == UserApprovalStatus.rejected.name.toLowerCase();          Color textBgColor = Color(0xFFF6F4F7);          Color textColor = Colors.black;          Color approvedIconBgColor = Color(0xFFF6F4F7);          Color approvedIconColor = Colors.grey.shade500;          Color rejectedIconBgColor = Color(0xFFF6F4F7);          Color rejectedIconColor = Colors.grey.shade500;          if (isApproved) {            approvedIconBgColor = Colors.green;            approvedIconColor = Colors.white;            textBgColor = Color(0xFFDCFFE7);            textColor = Colors.green.shade900;          } else if (isRejected) {            rejectedIconBgColor = Colors.red;            rejectedIconColor = Colors.white;            textBgColor = Color(0xFFF8E1DB);            textColor = Colors.red.shade900;          }          return Center(            child: Row(              mainAxisAlignment: MainAxisAlignment.center,              mainAxisSize: MainAxisSize.min,              children: [                SizedBox(width: 1.w),                Container(                  padding:                  EdgeInsets.symmetric(horizontal: 3.w, vertical: 1.1.h),                  decoration: BoxDecoration(                    color: textBgColor,                    borderRadius: BorderRadius.circular(4.h),                  ),                  child: Text(                    cell.value,                    style: TextStyle(                      fontSize: 9.5.sp,                      color: textColor,                      fontWeight: FontWeight.w600,                    ),                  ),                ),                SizedBox(width: 1.5.w),                if (!isShowingApprovedUsers)                  GestureDetector(                    onTap: () {                      updateUserStatus(user.userId, UserApprovalStatus.approved.name);                      onApproveReject.call(user.userId, UserApprovalStatus.approved.name);                    },                    child: Container(                      height: 3.6.h,                      width: 3.6.h,                      decoration: BoxDecoration(                        color: approvedIconBgColor,                        shape: BoxShape.circle,                      ),                      child: Icon(                        Icons.check,                        size: 14.sp,                        color: approvedIconColor,                      ),                    ),                  ),                if (!isShowingApprovedUsers) SizedBox(width: 1.5.w),                if (!isShowingApprovedUsers)                  GestureDetector(                    onTap: () {                      updateUserStatus(user.userId, UserApprovalStatus.rejected.name);                      onApproveReject.call(user.userId, UserApprovalStatus.rejected.name);                    },                    child: Container(                      height: 3.6.h,                      width: 3.6.h,                      decoration: BoxDecoration(                        color: rejectedIconBgColor,                        shape: BoxShape.circle,                      ),                      child: Icon(                        Icons.close,                        size: 14.sp,                        color: rejectedIconColor,                      ),                    ),                  ),                if (!isShowingApprovedUsers) SizedBox(width: 1.5.w),                if (!isShowingApprovedUsers)                  GestureDetector(                    onTap: () {                      onTapEdit(user);                    },                    child: Container(                      height: 3.6.h,                      width: 3.6.h,                      decoration: BoxDecoration(                        color: Color(0xFFF6F4F7),                        shape: BoxShape.circle,                      ),                      child: Icon(                        Icons.edit,                        size: 14.sp,                        color: Colors.grey.shade500,                      ),                    ),                  ),              ],            ),          );        }        return Center(          child: Padding(            padding: EdgeInsets.all(4.0),            child: Text(              cell.value.toString(),              style: TextStyle(                fontSize: 10.sp,                color: Colors.black,                fontWeight: FontWeight.w500,              ),            ),          ),        );      }).toList(),    );  }  @override  void handleSelectionChanged(      List<DataGridRow> addedRows, List<DataGridRow> removedRows) {    _selectedRows      ..removeWhere((row) => removedRows.contains(row))      ..addAll(addedRows);    for (final row in addedRows) {      final int rowIndex = _rows.indexOf(row);      final user = users[rowIndex];      onSelectUser(user);    }    for (final row in removedRows) {      final int rowIndex = _rows.indexOf(row);      final user = users[rowIndex];      onUnSelectUser(user);    }    notifyListeners();  }  void updateUserStatus(int? userId, String newStatus) {    final index = users.indexWhere((u) => u.userId == userId);    if (index != -1) {      users[index].approvalStatus = newStatus;      // Rebuild the row      final user = users[index];      _rows[index] = DataGridRow(cells: [        DataGridCell<String>(            columnName: 'First Name', value: user.firstName ?? '----'),        DataGridCell<String>(            columnName: 'Last Name', value: user.lastName ?? '----'),        DataGridCell<String>(            columnName: 'Mobile',            value: user.mobileNumber?.toString() ?? '----'),        DataGridCell<String>(columnName: 'Email', value: user.email ?? '----'),        DataGridCell<String>(            columnName: 'Organization', value: user.organisationType ?? '----'),        DataGridCell<String>(            columnName: 'Job Role', value: user.role ?? '----'),        DataGridCell<String>(            columnName: 'ID', value: user.employeeId ?? '----'),        DataGridCell<String>(            columnName: 'PAN', value: user.panCardNo ?? '----'),        DataGridCell<String>(            columnName: 'Adhar', value: user.aadharNo ?? '----'),        DataGridCell<String>(columnName: 'Photo', value: ''),        DataGridCell<String>(columnName: 'Status', value: newStatus),      ]);      notifyListeners(); // important!    }  }}